import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Rate Limiting","description":"","frontmatter":{},"headers":[],"relativePath":"api-documentation/v1/rate-limiting.md","filePath":"api-documentation/v1/rate-limiting.md"}'),r={name:"api-documentation/v1/rate-limiting.md"};function n(s,e,d,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h1><p>To protect Tradeboard from abuse and ensure fair usage, rate limits are enforced at both login and API levels. These limits are configurable via the <code>.env</code> file and apply globally per IP address.</p><h2 id="ui-login-rate-limits" tabindex="-1">UI Login Rate Limits <a class="header-anchor" href="#ui-login-rate-limits" aria-label="Permalink to &quot;UI Login Rate Limits&quot;">​</a></h2><p>Tradeboard applies two login-specific rate limits:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Limit</th><th>Description</th></tr></thead><tbody><tr><td>Per Minute</td><td>5 per minute</td><td>Allows a maximum of 5 login attempts per minute</td></tr><tr><td>Per Hour</td><td>25 per hour</td><td>Allows a maximum of 25 login attempts per hour</td></tr></tbody></table><p>These limits help prevent brute-force login attempts and secure user accounts.</p><h2 id="api-rate-limits" tabindex="-1">API Rate Limits <a class="header-anchor" href="#api-rate-limits" aria-label="Permalink to &quot;API Rate Limits&quot;">​</a></h2><p>Tradeboard implements differentiated rate limiting for various types of operations:</p><h3 id="order-management-apis" tabindex="-1">Order Management APIs <a class="header-anchor" href="#order-management-apis" aria-label="Permalink to &quot;Order Management APIs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>Limit</th><th>Description</th></tr></thead><tbody><tr><td>Per Second</td><td>10 per second</td><td>Order placement, modification, cancellation, and GTT writes</td></tr></tbody></table><p><strong>Applies to:</strong></p><ul><li><code>/api/v1/placeorder</code> - Place new orders</li><li><code>/api/v1/modifyorder</code> - Modify existing orders</li><li><code>/api/v1/cancelorder</code> - Cancel orders</li><li><code>/api/v1/optionsorder</code> and <code>/api/v1/optionsmultiorder</code> - Options execution</li><li><code>/api/v1/placegttorder</code>, <code>/api/v1/modifygttorder</code>, and <code>/api/v1/cancelgttorder</code> - GTT writes</li></ul><p><code>ORDER_RATE_LIMIT</code> does <strong>not</strong> cover every order-related route. <code>/api/v1/basketorder</code>, <code>/api/v1/splitorder</code>, <code>/api/v1/cancelallorder</code>, <code>/api/v1/closeposition</code>, and <code>/api/v1/gttorderbook</code> are decorated with <code>API_RATE_LIMIT</code> instead.</p><h3 id="smart-order-api" tabindex="-1">Smart Order API <a class="header-anchor" href="#smart-order-api" aria-label="Permalink to &quot;Smart Order API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>Limit</th><th>Description</th></tr></thead><tbody><tr><td>Per Second</td><td>10 per second</td><td>Position-aware smart order operations</td></tr></tbody></table><p><strong>Applies to:</strong></p><ul><li><code>/api/v1/placesmartorder</code> - Reconcile a symbol position to a target size</li></ul><p><code>SMART_ORDER_RATE_LIMIT</code> is independent from <code>ORDER_RATE_LIMIT</code>, even though both currently default to 10 per second.</p><h3 id="general-apis" tabindex="-1">General APIs <a class="header-anchor" href="#general-apis" aria-label="Permalink to &quot;General APIs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>Limit</th><th>Description</th></tr></thead><tbody><tr><td>Per Second</td><td>50 per second</td><td>All other API endpoints including market data</td></tr></tbody></table><p><strong>Applies to most other API endpoints including:</strong></p><ul><li>Market data APIs (quotes, multiquotes, depth, history, ticker, intervals)</li><li>Account APIs (funds, margin, positions, holdings)</li><li>Information APIs (orderbook, tradebook, orderstatus, openposition)</li><li>Search, symbol, expiry, instruments, option chain, and synthetic future</li><li>Analyzer, ping, chart preferences, sandbox P&amp;L, market holidays and timings</li></ul><h3 id="endpoints-with-their-own-limiter" tabindex="-1">Endpoints With Their Own Limiter <a class="header-anchor" href="#endpoints-with-their-own-limiter" aria-label="Permalink to &quot;Endpoints With Their Own Limiter&quot;">​</a></h3><p>Several resources do not use <code>API_RATE_LIMIT</code>. Each reads its own environment variable and falls back to the value shown when that variable is unset. These variables are not present in <code>.sample.env</code>, so the fallback is the effective default on a stock install.</p><table tabindex="0"><thead><tr><th>Environment variable</th><th>Fallback</th><th>Applies to</th></tr></thead><tbody><tr><td><code>GREEKS_RATE_LIMIT</code></td><td>30 per minute</td><td><code>/api/v1/optiongreeks</code></td></tr><tr><td><code>PORTFOLIO_API_RATE_LIMIT</code></td><td>10 per minute</td><td><code>/api/v1/portfolio/backtest</code>, <code>/api/v1/portfolio/holdings</code></td></tr><tr><td><code>PORTFOLIO_TEARSHEET_RATE_LIMIT</code></td><td>5 per minute</td><td><code>/api/v1/portfolio/tearsheet</code></td></tr><tr><td><code>SIP_API_RATE_LIMIT</code></td><td>10 per minute</td><td><code>/api/v1/sip/frequencies</code>, <code>/api/v1/sip/backtest</code></td></tr><tr><td><code>TELEGRAM_RATE_LIMIT</code></td><td>30 per minute</td><td>Telegram resources except broadcast</td></tr><tr><td>(hard-coded)</td><td>5 per minute</td><td><code>/api/v1/telegram/broadcast</code></td></tr><tr><td><code>WHATSAPP_RATE_LIMIT</code></td><td>30 per minute</td><td><code>/api/v1/whatsapp/notify</code></td></tr></tbody></table><p><code>/api/v1/multioptiongreeks</code> uses <code>API_RATE_LIMIT</code>, not <code>GREEKS_RATE_LIMIT</code>. <code>/api/v1/portfolio/benchmarks</code> also uses <code>API_RATE_LIMIT</code>.</p><p>Note that the in-code fallback for <code>API_RATE_LIMIT</code> itself is <code>10 per second</code>, lower than the <code>50 per second</code> that <code>.sample.env</code> ships. If <code>API_RATE_LIMIT</code> is absent from your <code>.env</code>, the effective limit is 10 per second, not 50.</p><h3 id="webhook-apis" tabindex="-1">Webhook APIs <a class="header-anchor" href="#webhook-apis" aria-label="Permalink to &quot;Webhook APIs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>Limit</th><th>Description</th></tr></thead><tbody><tr><td>Per Minute</td><td>100 per minute</td><td>External webhook endpoints from trading platforms</td></tr></tbody></table><p><strong>Applies to:</strong></p><ul><li><code>/strategy/webhook/&lt;token&gt;</code> - Strategy RMS webhook from external platforms</li><li><code>/chartink/webhook/&lt;webhook_id&gt;</code> - ChartInk webhook from external platforms</li></ul><p>These limits protect against external DoS attacks and webhook flooding.</p><h3 id="strategy-rms-browser-apis" tabindex="-1">Strategy RMS Browser APIs <a class="header-anchor" href="#strategy-rms-browser-apis" aria-label="Permalink to &quot;Strategy RMS Browser APIs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>Limit</th><th>Description</th></tr></thead><tbody><tr><td>Per Minute</td><td>200 per minute</td><td>Session-authenticated Strategy RMS configuration, operator, and detail calls</td></tr></tbody></table><p><strong>Applies to:</strong></p><ul><li><code>/strategy/api/strategies</code> - List and create strategies</li><li><code>/strategy/api/strategies/&lt;id&gt;</code> - Read, update, or delete a strategy</li><li><code>/strategy/api/strategies/&lt;id&gt;/start</code> and <code>/stop</code> - Browser lifecycle controls</li><li><code>/strategy/api/strategies/&lt;id&gt;/orderbook</code>, <code>/tradebook</code>, and <code>/positions</code> - Broker-backed detail data</li></ul><p>These are browser/session endpoints, not the public RESTX API. The nine API-key routes at <code>/api/v1/strategy/*</code> use <code>API_RATE_LIMIT</code>; see the <a href="./strategy-rms-api/README.html">Strategy RMS API</a>.</p><h2 id="configuration-via-env" tabindex="-1">Configuration via .env <a class="header-anchor" href="#configuration-via-env" aria-label="Permalink to &quot;Configuration via .env&quot;">​</a></h2><p>You can adjust the rate limits by editing the following variables in your <code>.env</code> file:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Login rate limits</span></span>
<span class="line"><span>LOGIN_RATE_LIMIT_MIN=&quot;5 per minute&quot;</span></span>
<span class="line"><span>LOGIN_RATE_LIMIT_HOUR=&quot;25 per hour&quot;</span></span>
<span class="line"><span>RESET_RATE_LIMIT=&quot;15 per hour&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># API rate limits</span></span>
<span class="line"><span>API_RATE_LIMIT=&quot;50 per second&quot;</span></span>
<span class="line"><span>ORDER_RATE_LIMIT=&quot;10 per second&quot;</span></span>
<span class="line"><span>SMART_ORDER_RATE_LIMIT=&quot;10 per second&quot;</span></span>
<span class="line"><span>WEBHOOK_RATE_LIMIT=&quot;100 per minute&quot;</span></span>
<span class="line"><span>STRATEGY_RATE_LIMIT=&quot;200 per minute&quot;</span></span></code></pre></div><p><code>RESET_RATE_LIMIT</code> (default <code>15 per hour</code>) applies to the password-reset flow, not to the v1 API.</p><p>These limits follow <a href="https://flask-limiter.readthedocs.io/en/stable/#rate-limit-string-format" target="_blank" rel="noreferrer">Flask-Limiter syntax</a> and support formats like:</p><ul><li><code>10 per second</code></li><li><code>100 per minute</code></li><li><code>1000 per day</code></li><li><code>10 per second;40 per minute</code> (compound: both limits enforced simultaneously)</li></ul><h2 id="what-happens-when-limits-are-exceeded" tabindex="-1">What Happens When Limits Are Exceeded <a class="header-anchor" href="#what-happens-when-limits-are-exceeded" aria-label="Permalink to &quot;What Happens When Limits Are Exceeded&quot;">​</a></h2><p>If a client exceeds any configured rate limit:</p><ol><li>The server will respond with HTTP status <code>429 Too Many Requests</code></li><li>Further requests will be blocked until the moving window permits another request</li></ol><p>Clients should not require a <code>Retry-After</code> header because header emission is not explicitly enabled in <code>limiter.py</code>.</p><h2 id="error-response" tabindex="-1">Error Response <a class="header-anchor" href="#error-response" aria-label="Permalink to &quot;Error Response&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Rate limit exceeded. Please try again later.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="security-impact" tabindex="-1">Security Impact <a class="header-anchor" href="#security-impact" aria-label="Permalink to &quot;Security Impact&quot;">​</a></h2><p>The rate limiting implementation provides essential protection:</p><h3 id="critical-protection" tabindex="-1">Critical Protection <a class="header-anchor" href="#critical-protection" aria-label="Permalink to &quot;Critical Protection&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Protection</th><th>Description</th></tr></thead><tbody><tr><td>External DoS Attacks</td><td>Webhook endpoints are protected from unlimited external requests</td></tr><tr><td>System Overload</td><td>Strategy operations are protected from flooding</td></tr><tr><td>Resource Exhaustion</td><td>Prevents accidental system overwhelming</td></tr></tbody></table><h3 id="attack-vector-mitigation" tabindex="-1">Attack Vector Mitigation <a class="header-anchor" href="#attack-vector-mitigation" aria-label="Permalink to &quot;Attack Vector Mitigation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Attack</th><th>Protection</th></tr></thead><tbody><tr><td>Webhook Flooding</td><td>External platforms cannot flood webhook endpoints</td></tr><tr><td>Strategy Abuse</td><td>Prevents rapid strategy creation/deletion attempts</td></tr><tr><td>Order Flooding</td><td>Prevents overwhelming the order management system</td></tr></tbody></table><h2 id="implementation-details" tabindex="-1">Implementation Details <a class="header-anchor" href="#implementation-details" aria-label="Permalink to &quot;Implementation Details&quot;">​</a></h2><h3 id="rate-limiting-strategy" tabindex="-1">Rate Limiting Strategy <a class="header-anchor" href="#rate-limiting-strategy" aria-label="Permalink to &quot;Rate Limiting Strategy&quot;">​</a></h3><p>Tradeboard uses the <strong>moving-window</strong> strategy for rate limiting, which provides more accurate rate limiting compared to fixed-window approaches.</p><h3 id="storage-backend" tabindex="-1">Storage Backend <a class="header-anchor" href="#storage-backend" aria-label="Permalink to &quot;Storage Backend&quot;">​</a></h3><p>Rate limit counters are stored in memory (<code>memory://</code>), which means:</p><ul><li>Fast performance with minimal latency</li><li>Counters reset when the application restarts</li><li>Suitable for single-user deployments</li></ul><h3 id="key-function" tabindex="-1">Key Function <a class="header-anchor" href="#key-function" aria-label="Permalink to &quot;Key Function&quot;">​</a></h3><p>Rate limits are applied per IP address using <code>get_remote_address</code> as the key function. Each unique IP address has its own rate limit counter.</p><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations&quot;">​</a></h2><h3 id="for-api-consumers" tabindex="-1">For API Consumers <a class="header-anchor" href="#for-api-consumers" aria-label="Permalink to &quot;For API Consumers&quot;">​</a></h3><ul><li>Avoid retrying failed login attempts rapidly</li><li>Spread out API requests using sleep/delay logic or a rate-limiter in your client code</li><li>Use queues or batching when dealing with large volumes of data or orders</li><li>Implement exponential backoff when receiving 429 errors</li></ul><h3 id="for-webhook-integration" tabindex="-1">For Webhook Integration <a class="header-anchor" href="#for-webhook-integration" aria-label="Permalink to &quot;For Webhook Integration&quot;">​</a></h3><ul><li>Ensure webhook calls are spread out appropriately</li><li>Implement retry logic with delays for webhook failures</li><li>Monitor webhook success rates to detect rate limiting</li></ul><h3 id="for-strategy-management" tabindex="-1">For Strategy Management <a class="header-anchor" href="#for-strategy-management" aria-label="Permalink to &quot;For Strategy Management&quot;">​</a></h3><ul><li>Avoid rapid creation/deletion of strategies</li><li>Batch symbol configuration operations when possible</li><li>Implement proper error handling for strategy operations</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h3><p><strong>&quot;Rate limit exceeded&quot; errors</strong></p><ul><li>Check your request frequency</li><li>Implement proper retry logic with delays</li><li>Consider using batch operations</li></ul><p><strong>Webhook failures</strong></p><ul><li>Verify webhook rate limits are appropriate for your platform</li><li>Check if external platforms are respecting rate limits</li><li>Monitor webhook logs for patterns</li></ul><p><strong>Strategy operation failures</strong></p><ul><li>Ensure strategy operations are not happening too rapidly</li><li>Check for automated scripts that might be creating excessive requests</li><li>Verify proper error handling in strategy management code</li></ul><h2 id="customization" tabindex="-1">Customization <a class="header-anchor" href="#customization" aria-label="Permalink to &quot;Customization&quot;">​</a></h2><p>To modify rate limits:</p><ol><li>Update the values in your <code>.env</code> file</li><li>Restart the application for changes to take effect</li></ol><p>Example customization:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Increase webhook rate limit for high-frequency platforms</span></span>
<span class="line"><span>WEBHOOK_RATE_LIMIT=&quot;200 per minute&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Decrease strategy operations for tighter control</span></span>
<span class="line"><span>STRATEGY_RATE_LIMIT=&quot;100 per minute&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Increase order rate limit for active trading</span></span>
<span class="line"><span>ORDER_RATE_LIMIT=&quot;20 per second&quot;</span></span></code></pre></div><hr><p><strong>Back to</strong>: <a href="./README.html">API Documentation</a></p>`,85)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
